<template>
  <div class="plans-page">
    <div class="page-hero"><div><span class="eyebrow">NEXT SESSION PLAN</span><h2>次日计划</h2><p>把收盘后的判断，整理成明天开盘前能直接执行的动作。</p></div><el-button type="primary" @click="openPlan()">新建计划</el-button></div>
    <div class="stats-row"><el-card><span>全部计划</span><strong>{{ plans.length }}</strong></el-card><el-card><span>待执行</span><strong>{{ pendingCount }}</strong></el-card><el-card><span>本周完成</span><strong>{{ completedCount }}</strong></el-card><el-card><span>当前目标仓位</span><strong>{{ nextPlan?.targetPosition ?? '-' }}<small>%</small></strong></el-card></div>
    <div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索市场前提、标的或计划交易" class="search"/><el-select v-model="status" clearable placeholder="全部状态"><el-option label="草稿" value="DRAFT"/><el-option label="执行中" value="ACTIVE"/><el-option label="已完成" value="COMPLETED"/><el-option label="已取消" value="CANCELLED"/></el-select><el-date-picker v-model="date" value-format="YYYY-MM-DD" clearable placeholder="交易日"/><el-button text @click="clearFilters">清空筛选</el-button></div>
    <div v-if="filteredPlans.length" class="plan-list"><el-card v-for="plan in filteredPlans" :key="plan.id" class="plan-card"><div class="plan-head"><div><div class="plan-date">{{ plan.tradeDate }} <el-tag size="small" :type="statusType(plan.status)">{{ statusLabel(plan.status) }}</el-tag></div><h3>{{ plan.marketPremise || '未填写市场前提' }}</h3></div><div class="plan-actions"><el-button link @click="openPlan(plan)">编辑</el-button><el-button link type="danger" @click="removePlanRow(plan.id)">删除</el-button></div></div><div class="plan-grid"><div><span>目标仓位</span><b>{{ plan.targetPosition ?? '-' }}%</b></div><div><span>关注标的</span><p>{{ plan.watchStocks || '未填写' }}</p></div><div><span>计划交易</span><p>{{ plan.plannedTrades || '未填写' }}</p></div><div><span>风险控制</span><p>{{ plan.riskControls || '未填写' }}</p></div></div><div v-if="plan.reportNote" class="plan-note">备注：{{ plan.reportNote }}</div></el-card></div><el-empty v-else description="没有匹配的次日计划"/>
    <el-dialog v-model="visible" :title="editingId ? '编辑次日计划' : '新建次日计划'" width="min(760px,96vw)" :close-on-click-modal="false"><el-form label-position="top"><div class="form-grid"><el-form-item label="交易日"><el-date-picker v-model="form.tradeDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="执行状态"><el-select v-model="form.status"><el-option label="草稿" value="DRAFT"/><el-option label="执行中" value="ACTIVE"/><el-option label="已完成" value="COMPLETED"/><el-option label="已取消" value="CANCELLED"/></el-select></el-form-item><el-form-item label="目标仓位 %"><el-input-number v-model="form.targetPosition" :min="0" :max="100"/></el-form-item><el-form-item label="关联提醒 ID"><el-input v-model="form.ruleIds" placeholder="规则 ID，例如 12,15"/><el-input v-model="form.reminderIds" placeholder="例如 12,15"/></el-form-item></div><el-form-item label="市场前提"><el-input v-model="form.marketPremise" type="textarea" :rows="3" placeholder="明天最重要的市场判断是什么？"/></el-form-item><el-form-item label="关注标的"><el-input v-model="form.watchStocks" type="textarea" :rows="2"/></el-form-item><el-form-item label="计划交易"><el-input v-model="form.plannedTrades" type="textarea" :rows="3" placeholder="什么条件下买入、卖出或继续观察？"/></el-form-item><el-form-item label="风险控制"><el-input v-model="form.riskControls" type="textarea" :rows="3"/></el-form-item><el-form-item label="报告备注"><el-input v-model="form.reportNote"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存计划</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import * as api from '@/api/tradingReview';
import type { NextPlan } from '@/api/tradingReview';
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const plans=ref<NextPlan[]>([]),keyword=ref(''),status=ref(''),date=ref(''),visible=ref(false),editingId=ref<number>();
const blank=():api.PlanPayload=>({tradeDate:today(),marketPremise:'',targetPosition:0,watchStocks:'',plannedTrades:'',riskControls:'',reminderIds:'',ruleIds:'',reportNote:'',status:'DRAFT'});const form=reactive<api.PlanPayload>(blank());
const filteredPlans=computed(()=>plans.value.filter(plan=>(!status.value||plan.status===status.value)&&(!date.value||plan.tradeDate===date.value)&&(!keyword.value||[plan.marketPremise,plan.watchStocks,plan.plannedTrades,plan.riskControls].some(value=>value?.toLowerCase().includes(keyword.value.toLowerCase())))).sort((a,b)=>b.tradeDate.localeCompare(a.tradeDate)));
const pendingCount=computed(()=>plans.value.filter(plan=>plan.status==='DRAFT'||plan.status==='ACTIVE').length);const completedCount=computed(()=>plans.value.filter(plan=>plan.status==='COMPLETED').length);const nextPlan=computed(()=>plans.value.find(plan=>plan.status==='ACTIVE')||plans.value.find(plan=>plan.status==='DRAFT'));
function statusLabel(value:string){return ({DRAFT:'草稿',ACTIVE:'执行中',COMPLETED:'已完成',CANCELLED:'已取消'} as Record<string,string>)[value]||value;}function statusType(value:string){return value==='ACTIVE'?'warning':value==='COMPLETED'?'success':value==='CANCELLED'?'info':'';}
function openPlan(plan?:NextPlan){editingId.value=plan?.id;Object.assign(form,plan||blank());visible.value=true;}async function load(){plans.value=(await api.listPlans()).data;}async function save(){if(!form.tradeDate||!(form.marketPremise||'').trim()){ElMessage.warning('请填写交易日和市场前提');return;}await api.savePlan(form,editingId.value);visible.value=false;editingId.value=undefined;ElMessage.success('次日计划已保存');await load();}async function removePlanRow(planId:number){await ElMessageBox.confirm('删除后不可恢复，是否继续？','确认删除',{type:'warning'});await api.removePlan(planId);await load();}function clearFilters(){keyword.value='';status.value='';date.value='';}onMounted(load);
</script>
<style scoped>
.plans-page{display:flex;flex-direction:column;gap:18px}.page-hero{display:flex;justify-content:space-between;align-items:flex-end;padding:28px 30px;border-radius:24px;color:#fff;background:linear-gradient(135deg,#0f172a,#1e3a5f 58%,#0f766e);box-shadow:0 16px 36px rgb(15 23 42 / 14%)}.eyebrow{font-size:11px;letter-spacing:.2em;color:#5eead4}.page-hero h2{margin:7px 0;font-size:30px}.page-hero p{margin:0;color:#cbd5e1}.stats-row{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stats-row :deep(.el-card){border:1px solid #e2e8f0;border-radius:16px}.stats-row span,.stats-row strong{display:block}.stats-row span{color:#64748b;font-size:12px}.stats-row strong{margin-top:7px;color:#0f172a;font-size:25px}.stats-row small{font-size:13px;color:#64748b}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.search{max-width:420px;flex:1 1 280px}.plan-list{display:flex;flex-direction:column;gap:14px}.plan-card{border:1px solid #e2e8f0!important;border-radius:16px!important}.plan-head{display:flex;justify-content:space-between;gap:14px}.plan-date{color:#64748b;font-size:13px}.plan-date .el-tag{margin-left:8px}.plan-card h3{margin:9px 0 0;color:#0f172a;font-size:18px}.plan-actions{white-space:nowrap}.plan-grid{display:grid;grid-template-columns:130px repeat(3,1fr);gap:12px;margin-top:18px}.plan-grid>div{padding:13px;border-radius:12px;background:#f8fafc}.plan-grid span{display:block;color:#94a3b8;font-size:11px}.plan-grid b{display:block;margin-top:8px;color:#2563eb;font-size:22px}.plan-grid p{margin:7px 0 0;color:#475569;font-size:13px;line-height:1.55}.plan-note{margin-top:14px;padding-top:12px;border-top:1px solid #eef2f7;color:#64748b;font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid :deep(.el-date-editor),.form-grid :deep(.el-select),.form-grid :deep(.el-input-number){width:100%}@media(max-width:800px){.stats-row{grid-template-columns:repeat(2,1fr)}.plan-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.page-hero{align-items:flex-start;flex-direction:column;gap:16px;padding:22px 18px}.toolbar>*{flex:1 1 100%;max-width:none}.plan-head{align-items:flex-start;flex-direction:column}.plan-grid,.form-grid{grid-template-columns:1fr}}
</style>
